// La herramienta recibe en «query» el texto que manda el agente, con uno o varios números 0x...
// Las cuentas se hacen con BigInt: un saldo en wei tiene hasta 25 cifras y un Number común las redondea.
const texto = typeof query === 'string' ? query : JSON.stringify(query ?? '');
const numeros = (texto.match(/0x[0-9a-fA-F]+/g) ?? []).slice(0, 10);
if (!numeros.length) {
  return 'Necesito uno o varios números hexadecimales que empiecen con 0x, por ejemplo 0x2386f26fc10000.';
}

// 1234500000000000000 con 18 decimales -> «1.2345»
const conDecimales = (valor, decimales) => {
  const base = 10n ** BigInt(decimales);
  const resto = (valor % base).toString().padStart(decimales, '0').replace(/0+$/, '');
  return resto ? `${valor / base}.${resto}` : `${valor / base}`;
};

const resultado = numeros.map((hex) => {
  const n = BigInt(hex);
  return {
    hexadecimal: hex,
    decimal: n.toString(),
    si_son_wei_en_avax: conDecimales(n, 18),
    si_son_wei_en_gwei: conDecimales(n, 9),
  };
});
return JSON.stringify(resultado);
